835	     1	#!/usr/bin/env bash
836	     2	#
837	     3	# check-architecture.sh - Verify layer boundary constraints
838	     4	#
839	     5	# Checks that:
840	     6	# 1. No Node.js core modules (fs, path, os, child_process) in renderer code
841	     7	# 2. No Electron IPC imports in service code
842	     8	# 3. No React imports in services or main process code
843	     9	#
844	    10	# Exit code 0 = all checks pass
845	    11	# Exit code 1 = violations found
846	    12	
847	    13	set -euo pipefail
848	    14	
849	    15	VIOLATIONS=0
850	    16	
851	    17	echo "=== Architecture Boundary Checks ==="
852	    18	echo ""
853	    19	
854	    20	# Check 1: No fs/path imports in renderer
855	    21	echo "Checking renderer for Node.js core module imports..."
856	    22	RENDERER_FILES=$(find src/renderer -name '*.ts' -o -name '*.tsx' 2>/dev/null || true)
857	    23	if [ -n "$RENDERER_FILES" ]; then
858	    24	  while IFS= read -r file; do
859	    25	    if grep -qE "import.*\b(fs|path|os|child_process)\b" "$file" 2>/dev/null; then
860	    26	      echo "  VIOLATION: $file imports Node.js core module"
861	    27	      VIOLATIONS=$((VIOLATIONS + 1))
862	    28	    fi
863	    29	  done <<< "$RENDERER_FILES"
864	    30	fi
865	    31	if [ "$VIOLATIONS" -eq 0 ]; then
866	    32	  echo "  PASS: No Node.js core imports in renderer"
867	    33	fi
868	    34	echo ""
869	    35	
870	    36	# Check 2: No Electron IPC in services
871	    37	echo "Checking services for Electron IPC imports..."
872	    38	SERVICE_FILES=$(find src/services -name '*.ts' 2>/dev/null || true)
873	    39	SVIO=0
874	    40	if [ -n "$SERVICE_FILES" ]; then
875	    41	  while IFS= read -r file; do
876	    42	    if grep -qE "import.*from\s+['\"]electron['\"]" "$file" 2>/dev/null; then
877	    43	      echo "  VIOLATION: $file imports from electron"
878	    44	      VIOLATIONS=$((VIOLATIONS + 1))
879	    45	      SVIO=$((SVIO + 1))
880	    46	    fi
881	    47	    if grep -qE "\bipcMain\b|\bipcRenderer\b|\bBrowserWindow\b" "$file" 2>/dev/null; then
882	    48	      echo "  VIOLATION: $file uses Electron IPC"
883	    49	      VIOLATIONS=$((VIOLATIONS + 1))
884	    50	      SVIO=$((SVIO + 1))
885	    51	    fi
886	    52	  done <<< "$SERVICE_FILES"
887	    53	fi
888	    54	if [ "$SVIO" -eq 0 ]; then
889	    55	  echo "  PASS: No Electron IPC in services"
890	    56	fi
891	    57	echo ""
892	    58	
893	    59	# Check 3: No React imports in services or main
894	    60	echo "Checking services and main for React imports..."
895	    61	BACKEND_FILES=$(find src/services src/main -name '*.ts' 2>/dev/null || true)
896	    62	RVIO=0
897	    63	if [ -n "$BACKEND_FILES" ]; then
898	    64	  while IFS= read -r file; do
899	    65	    if grep -qE "import.*from\s+['\"]react['\"]" "$file" 2>/dev/null; then
900	    66	      echo "  VIOLATION: $file imports React"
901	    67	      VIOLATIONS=$((VIOLATIONS + 1))
902	    68	      RVIO=$((RVIO + 1))
903	    69	    fi
904	    70	  done <<< "$BACKEND_FILES"
905	    71	fi
906	    72	if [ "$RVIO" -eq 0 ]; then
907	    73	  echo "  PASS: No React imports in services/main"
908	    74	fi
909	    75	echo ""
910	    76	
911	    77	# Summary
912	    78	echo "=== Summary ==="
913	    79	if [ "$VIOLATIONS" -gt 0 ]; then
914	    80	  echo "FAIL: $VIOLATIONS violation(s) found"
915	    81	  exit 1
