     1	#!/usr/bin/env bash
     2	#
     3	# check-architecture.sh - Verify layer boundary constraints
     4	#
     5	# Checks that:
     6	# 1. No Node.js core modules (fs, path, os, child_process) in renderer code
     7	# 2. No Electron IPC imports in service code
     8	# 3. No React imports in services or main process code
     9	#
    10	# Exit code 0 = all checks pass
    11	# Exit code 1 = violations found
    12	
    13	set -euo pipefail
    14	
    15	VIOLATIONS=0
    16	
    17	echo "=== Architecture Boundary Checks ==="
    18	echo ""
    19	
    20	# Check 1: No fs/path imports in renderer
    21	echo "Checking renderer for Node.js core module imports..."
    22	RENDERER_FILES=$(find src/renderer -name '*.ts' -o -name '*.tsx' 2>/dev/null || true)
    23	if [ -n "$RENDERER_FILES" ]; then
    24	  while IFS= read -r file; do
    25	    if grep -qE "import.*\b(fs|path|os|child_process)\b" "$file" 2>/dev/null; then
    26	      echo "  VIOLATION: $file imports Node.js core module"
    27	      VIOLATIONS=$((VIOLATIONS + 1))
    28	    fi
    29	  done <<< "$RENDERER_FILES"
    30	fi
    31	if [ "$VIOLATIONS" -eq 0 ]; then
    32	  echo "  PASS: No Node.js core imports in renderer"
    33	fi
    34	echo ""
    35	
    36	# Check 2: No Electron IPC in services
    37	echo "Checking services for Electron IPC imports..."
    38	SERVICE_FILES=$(find src/services -name '*.ts' 2>/dev/null || true)
    39	SVIO=0
    40	if [ -n "$SERVICE_FILES" ]; then
    41	  while IFS= read -r file; do
    42	    if grep -qE "import.*from\s+['\"]electron['\"]" "$file" 2>/dev/null; then
    43	      echo "  VIOLATION: $file imports from electron"
    44	      VIOLATIONS=$((VIOLATIONS + 1))
    45	      SVIO=$((SVIO + 1))
    46	    fi
    47	    if grep -qE "\bipcMain\b|\bipcRenderer\b|\bBrowserWindow\b" "$file" 2>/dev/null; then
    48	      echo "  VIOLATION: $file uses Electron IPC"
    49	      VIOLATIONS=$((VIOLATIONS + 1))
    50	      SVIO=$((SVIO + 1))
    51	    fi
    52	  done <<< "$SERVICE_FILES"
    53	fi
    54	if [ "$SVIO" -eq 0 ]; then
    55	  echo "  PASS: No Electron IPC in services"
    56	fi
    57	echo ""
    58	
    59	# Check 3: No React imports in services or main
    60	echo "Checking services and main for React imports..."
    61	BACKEND_FILES=$(find src/services src/main -name '*.ts' 2>/dev/null || true)
    62	RVIO=0
    63	if [ -n "$BACKEND_FILES" ]; then
    64	  while IFS= read -r file; do
    65	    if grep -qE "import.*from\s+['\"]react['\"]" "$file" 2>/dev/null; then
    66	      echo "  VIOLATION: $file imports React"
    67	      VIOLATIONS=$((VIOLATIONS + 1))
    68	      RVIO=$((RVIO + 1))
    69	    fi
    70	  done <<< "$BACKEND_FILES"
    71	fi
    72	if [ "$RVIO" -eq 0 ]; then
    73	  echo "  PASS: No React imports in services/main"
    74	fi
    75	echo ""
    76	
    77	# Summary
    78	echo "=== Summary ==="
    79	if [ "$VIOLATIONS" -gt 0 ]; then
    80	  echo "FAIL: $VIOLATIONS violation(s) found"
    81	  exit 1
    82	else
    83	  echo "PASS: All architecture boundary checks passed"
    84	  exit 0
    85	fi
