import { useEffect, useRef, useState, type CSSProperties } from 'react';
import { ConversationMessage } from '../../shared/types';
import { CitationList } from './CitationList';
import { formatFullTimestamp, formatTimestamp } from '../utils/format';

export interface PendingQuestion {
  question: string;
  askedAt: string;
}

export interface FailedQuestion extends PendingQuestion {
  error: string;
}

export interface TurnFocusRequest {
  turnId: string;
  /** Changes on every request so selecting the same turn twice still scrolls. */
  nonce: number;
}

interface Props {
  messages: ConversationMessage[];
  pending: PendingQuestion | null;
  failed: FailedQuestion | null;
  loadError: string | null;
  focusRequest: TurnFocusRequest | null;
  onAsk: (question: string) => void;
  onRetry: () => void;
  onDismissError: () => void;
  onReloadHistory: () => void;
  onClearHistory: () => Promise<void>;
  isDocumentAvailable: (documentId: string) => boolean;
  onOpenDocument: (documentId: string) => void;
}

const EXAMPLE_QUESTIONS = [
  'How does the indexing pipeline work?',
  'What was decided in the meeting?',
  'How are documents imported?',
];

const smallButton: CSSProperties = {
  padding: '3px 10px',
  background: 'transparent',
  color: '#c0c0dd',
  border: '1px solid #2a2a5e',
  borderRadius: '3px',
  cursor: 'pointer',
  fontSize: '11px',
};

const metaText: CSSProperties = { fontSize: '11px', color: '#a8a8c8' };

function Timestamp({ iso }: { iso: string }) {
  return (
    <time dateTime={iso} title={formatFullTimestamp(iso)} style={metaText}>
      {formatTimestamp(iso)}
    </time>
  );
}

function CopyButton({ text }: { text: string }) {
  const [state, setState] = useState<'idle' | 'copied' | 'failed'>('idle');

  useEffect(() => {
    if (state === 'idle') return;
    const t = setTimeout(() => setState('idle'), 2000);
    return () => clearTimeout(t);
  }, [state]);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setState('copied');
    } catch {
      setState('failed');
    }
  };

  return (
    <button type="button" onClick={copy} style={smallButton} aria-label="Copy answer">
      {state === 'copied' ? 'Copied' : state === 'failed' ? 'Copy failed' : 'Copy'}
      <span className="sr-only" aria-live="polite">
        {state === 'copied' ? 'Answer copied to clipboard' : state === 'failed' ? 'Could not copy answer' : ''}
      </span>
    </button>
  );
}

function bubble(role: 'user' | 'assistant', highlighted: boolean): CSSProperties {
  const isUser = role === 'user';
  return {
    alignSelf: isUser ? 'flex-end' : 'flex-start',
    maxWidth: isUser ? '75%' : '85%',
    minWidth: 0,
    padding: '10px 14px',
    borderRadius: isUser ? '10px 10px 2px 10px' : '10px 10px 10px 2px',
    background: isUser ? '#533483' : '#1a1a3e',
    border: `1px solid ${highlighted ? '#9d7fe0' : isUser ? '#533483' : '#0f3460'}`,
    boxShadow: highlighted ? '0 0 0 2px rgba(157,127,224,0.35)' : 'none',
    transition: 'box-shadow 0.3s, border-color 0.3s',
  };
}

const messageText: CSSProperties = {
  fontSize: '14px',
  lineHeight: 1.6,
  whiteSpace: 'pre-wrap',
  overflowWrap: 'anywhere',
};

/** Multi-turn Q&A: the conversation thread plus the question composer. */
export function QuestionPanel({
  messages,
  pending,
  failed,
  loadError,
  focusRequest,
  onAsk,
  onRetry,
  onDismissError,
  onReloadHistory,
  onClearHistory,
  isDocumentAvailable,
  onOpenDocument,
}: Props) {
  const [question, setQuestion] = useState('');
  const [confirmingClear, setConfirmingClear] = useState(false);
  const [highlightedTurn, setHighlightedTurn] = useState<string | null>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const bottomRef = useRef<HTMLDivElement>(null);
  const turnRefs = useRef(new Map<string, HTMLLIElement>());

  const turnCount = messages.filter(m => m.role === 'user').length;

  // Keep the newest exchange in view when messages arrive or a question is pending/fails.
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ block: 'end' });
  }, [messages.length, pending, failed]);

  // Jump to a turn selected from the History outline.
  useEffect(() => {
    if (!focusRequest) return;
    const el = turnRefs.current.get(focusRequest.turnId);
    if (!el) return;
    el.scrollIntoView({ block: 'start', behavior: 'smooth' });
    el.focus({ preventScroll: true });
    setHighlightedTurn(focusRequest.turnId);
    const t = setTimeout(() => setHighlightedTurn(null), 2000);
    return () => clearTimeout(t);
  }, [focusRequest]);

  const fillInput = (text: string) => {
    setQuestion(text);
    inputRef.current?.focus();
  };

  const submit = () => {
    const trimmed = question.trim();
    if (!trimmed || pending) return;
    onAsk(trimmed);
    setQuestion('');
  };

  const handleClear = async () => {
    await onClearHistory();
    setConfirmingClear(false);
  };

  const isEmpty = messages.length === 0 && !pending && !failed && !loadError;

  return (
    <section
      aria-labelledby="conversation-heading"
      style={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column', borderTop: '1px solid #0f3460' }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '8px',
          padding: '8px 20px',
          background: '#16213e',
          borderBottom: '1px solid #0f3460',
        }}
      >
        <h2 id="conversation-heading" style={{ fontSize: '14px', fontWeight: 600 }}>
          Conversation
          <span style={{ ...metaText, fontWeight: 400, marginLeft: '8px' }}>
            {turnCount} {turnCount === 1 ? 'exchange' : 'exchanges'}
          </span>
        </h2>
        {turnCount > 0 &&
          (confirmingClear ? (
            <div role="group" aria-label="Confirm clearing history" style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
              <span style={{ fontSize: '12px' }}>Delete all {turnCount} exchanges?</span>
              <button type="button" onClick={handleClear} style={{ ...smallButton, background: '#8b2c3c', color: '#fff', borderColor: '#8b2c3c' }}>
                Delete
              </button>
              <button type="button" onClick={() => setConfirmingClear(false)} style={smallButton} autoFocus>
                Cancel
              </button>
            </div>
          ) : (
            <button type="button" onClick={() => setConfirmingClear(true)} style={smallButton}>
              Clear history
            </button>
          ))}
      </div>

      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', padding: '16px 20px' }}>
        {loadError && (
          <div role="alert" style={{ padding: '10px 14px', marginBottom: '12px', background: '#3a1a2a', border: '1px solid #8b2c3c', borderRadius: '6px', fontSize: '13px' }}>
            Couldn't load conversation history: {loadError}{' '}
            <button type="button" onClick={onReloadHistory} style={smallButton}>
              Try again
            </button>
          </div>
        )}

        {isEmpty && (
          <div style={{ textAlign: 'center', paddingTop: '24px', color: '#a8a8c8', fontSize: '13px' }}>
