  const turnCount = messages.filter(m => m.role === 'user').length;

  // Keep the newest exchange in view when messages arrive or a question is pending/fails.
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ block: 'end' });
  }, [messages.length, pending, failed]);

  // Jump to a turn selected from the History outline.
  useEffect(() => {
    if (!focusRequest) return;
    const el = turnRefs.current.get(focusRequest.turnId);
    if (!el) return;
    el.scrollIntoView({ block: 'start', behavior: 'smooth' });
    el.focus({ preventScroll: true });
    setHighlightedTurn(focusRequest.turnId);
    const t = setTimeout(() => setHighlightedTurn(null), 2000);
    return () => clearTimeout(t);
  }, [focusRequest]);

  const fillInput = (text: string) => {
    setQuestion(text);
    inputRef.current?.focus();
  };

  const submit = () => {
    const trimmed = question.trim();
    if (!trimmed || pending) return;
    onAsk(trimmed);
    setQuestion('');
  };

  const handleClear = async () => {
    await onClearHistory();
    setConfirmingClear(false);
  };

  const isEmpty = messages.length === 0 && !pending && !failed && !loadError;

  return (
    <section
      aria-labelledby="conversation-heading"
      style={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column', borderTop: '1px solid #0f3460' }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '8px',
          padding: '8px 20px',
          background: '#16213e',
          borderBottom: '1px solid #0f3460',
        }}
      >
        <h2 id="conversation-heading" style={{ fontSize: '14px', fontWeight: 600 }}>
          Conversation
          <span style={{ ...metaText, fontWeight: 400, marginLeft: '8px' }}>
            {turnCount} {turnCount === 1 ? 'exchange' : 'exchanges'}
          </span>
        </h2>
        {turnCount > 0 &&
          (confirmingClear ? (
            <div role="group" aria-label="Confirm clearing history" style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
              <span style={{ fontSize: '12px' }}>Delete all {turnCount} exchanges?</span>
              <button type="button" onClick={handleClear} style={{ ...smallButton, background: '#8b2c3c', color: '#fff', borderColor: '#8b2c3c' }}>
                Delete
              </button>
              <button type="button" onClick={() => setConfirmingClear(false)} style={smallButton} autoFocus>
                Cancel
              </button>
            </div>
          ) : (
            <button type="button" onClick={() => setConfirmingClear(true)} style={smallButton}>
              Clear history
            </button>
          ))}
      </div>

      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', padding: '16px 20px' }}>
        {loadError && (
          <div role="alert" style={{ padding: '10px 14px', marginBottom: '12px', background: '#3a1a2a', border: '1px solid #8b2c3c', borderRadius: '6px', fontSize: '13px' }}>
            Couldn't load conversation history: {loadError}{' '}
            <button type="button" onClick={onReloadHistory} style={smallButton}>
              Try again
            </button>
          </div>
        )}

        {isEmpty && (
          <div style={{ textAlign: 'center', paddingTop: '24px', color: '#a8a8c8', fontSize: '13px' }}>
            <p>No questions yet. Ask something about your documents — follow-up questions can build on earlier ones.</p>
            <ul style={{ listStyle: 'none', marginTop: '12px', display: 'flex', flexWrap: 'wrap', gap: '8px', justifyContent: 'center' }}>
              {EXAMPLE_QUESTIONS.map(q => (
                <li key={q}>
                  <button type="button" onClick={() => fillInput(q)} style={{ ...smallButton, fontSize: '12px', padding: '5px 12px' }}>
                    {q}
                  </button>
                </li>
              ))}
            </ul>
          </div>
        )}

        <ol aria-label="Questions and answers" style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {messages.map(m => {
            const highlighted = highlightedTurn === m.turnId;
            if (m.role === 'user') {
              return (
                <li
                  key={m.id}
                  ref={el => {
                    if (el) turnRefs.current.set(m.turnId, el);
                    else turnRefs.current.delete(m.turnId);
                  }}
                  tabIndex={-1}
                  aria-label={`You asked, ${formatTimestamp(m.timestamp)}`}
                  style={{ display: 'flex', flexDirection: 'column', marginTop: '8px', scrollMarginTop: '8px', borderRadius: '10px' }}
                >
                  <article style={bubble('user', highlighted)}>
                    <header style={{ display: 'flex', justifyContent: 'space-between', gap: '12px', marginBottom: '4px' }}>
                      <span style={{ fontSize: '11px', fontWeight: 600, color: '#e8dcff' }}>You</span>
                      <Timestamp iso={m.timestamp} />
                    </header>
                    <p style={messageText}>{m.content}</p>
                    <div style={{ marginTop: '6px', textAlign: 'right' }}>
                      <button type="button" onClick={() => fillInput(m.content)} style={{ ...smallButton, color: '#e8dcff', borderColor: '#7a5bb5' }}>
                        Edit &amp; ask again
                      </button>
                    </div>
                  </article>
                </li>
              );
            }
            const confidence = m.confidence !== undefined ? Math.round(m.confidence * 100) : null;
            return (
              <li key={m.id} aria-label={`Assistant answered, ${formatTimestamp(m.timestamp)}`} style={{ display: 'flex', flexDirection: 'column' }}>
                <article style={bubble('assistant', highlighted)}>
                  <header style={{ display: 'flex', justifyContent: 'space-between', gap: '12px', marginBottom: '4px' }}>
                    <span style={{ fontSize: '11px', fontWeight: 600, color: '#9d7fe0' }}>Assistant</span>
                    <Timestamp iso={m.timestamp} />
                  </header>
                  <p style={messageText}>{m.content}</p>
                  {m.usedConversationContext && (
                    <p style={{ ...metaText, marginTop: '6px', fontStyle: 'italic' }}>Interpreted as a follow-up to your previous question.</p>
                  )}
                  <CitationList citations={m.citations ?? []} isDocumentAvailable={isDocumentAvailable} onOpenDocument={onOpenDocument} />
                  <footer style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '8px', marginTop: '8px' }}>
                    <span style={metaText}>{confidence !== null ? `Confidence ${confidence}%` : ''}</span>
                    <CopyButton text={m.content} />
                  </footer>
                </article>
              </li>
            );
          })}

          {(pending || failed) && (
            <li style={{ display: 'flex', flexDirection: 'column', gap: '10px', marginTop: '8px' }}>
              <article style={{ ...bubble('user', false), opacity: failed ? 0.7 : 1 }}>
                <header style={{ display: 'flex', justifyContent: 'space-between', gap: '12px', marginBottom: '4px' }}>
                  <span style={{ fontSize: '11px', fontWeight: 600, color: '#e8dcff' }}>You</span>
                  <Timestamp iso={(pending ?? failed)!.askedAt} />
                </header>
                <p style={messageText}>{(pending ?? failed)!.question}</p>
              </article>
              {pending ? (
                <div role="status" style={{ ...bubble('assistant', false), color: '#a8a8c8', fontSize: '13px', fontStyle: 'italic' }}>
                  Searching your documents…
                </div>
              ) : (
                <div role="alert" style={{ ...bubble('assistant', false), background: '#3a1a2a', borderColor: '#8b2c3c', fontSize: '13px' }}>
                  <p>Couldn't get an answer: {failed!.error}</p>
                  <div style={{ display: 'flex', gap: '6px', marginTop: '8px' }}>
                    <button type="button" onClick={onRetry} style={{ ...smallButton, color: '#fff' }}>
                      Retry
                    </button>
                    <button type="button" onClick={onDismissError} style={smallButton}>
                      Dismiss
                    </button>
                  </div>
                </div>
              )}
            </li>
          )}
        </ol>
        <div ref={bottomRef} />
      </div>

      <form
        onSubmit={e => {
          e.preventDefault();
          submit();
        }}
        style={{ display: 'flex', alignItems: 'flex-end', padding: '12px 20px', borderTop: '1px solid #0f3460', background: '#16213e' }}
      >
        <label htmlFor="question-input" className="sr-only">
          Ask a question about your documents
        </label>
        <textarea
          id="question-input"
          ref={inputRef}
          value={question}
          rows={2}
          onChange={e => setQuestion(e.target.value)}
          onKeyDown={e => {
            if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
              e.preventDefault();
              submit();
            }
          }}
          placeholder={turnCount > 0 ? 'Ask a follow-up question…' : 'Ask a question about your documents…'}
          aria-describedby="question-hint"
          style={{
            flex: 1,
            resize: 'none',
            padding: '10px 14px',
            background: '#1a1a2e',
            color: '#e0e0e0',
            border: '1px solid #0f3460',
            borderRadius: '6px',
            fontSize: '14px',
            fontFamily: 'inherit',
            lineHeight: 1.4,
          }}
        />
        <span id="question-hint" className="sr-only">
          Press Enter to send, Shift+Enter for a new line.
        </span>
        <button
          type="submit"
          disabled={!question.trim() || pending !== null}
          style={{
            marginLeft: '10px',
            padding: '10px 20px',
            background: '#533483',
            color: '#fff',
            border: 'none',
            borderRadius: '6px',
            cursor: !question.trim() || pending ? 'not-allowed' : 'pointer',
            opacity: !question.trim() || pending ? 0.6 : 1,
            fontSize: '14px',
            fontWeight: 500,
          }}
        >
          {pending ? 'Asking…' : 'Ask'}
        </button>
      </form>
    </section>
  );
}

