import { ConversationMessage } from '../../shared/types';
import { formatFullTimestamp, formatTimestamp } from '../utils/format';

interface Props {
  messages: ConversationMessage[];
  onSelectTurn: (turnId: string) => void;
}

/** Outline of past questions in the sidebar; selecting one jumps to it in the conversation. */
export function ConversationHistory({ messages, onSelectTurn }: Props) {
  const questions = messages.filter(m => m.role === 'user');

  if (questions.length === 0) {
    return (
      <p style={{ padding: '20px', color: '#a8a8c8', textAlign: 'center', fontSize: '13px' }}>
        No conversation history yet. Ask a question to get started.
      </p>
    );
  }

  return (
    <nav aria-label="Conversation history" style={{ flex: 1, overflowY: 'auto' }}>
      <ol style={{ listStyle: 'none' }}>
        {questions.map(q => (
          <li key={q.id}>
            <button
              type="button"
              onClick={() => onSelectTurn(q.turnId)}
              title={q.content}
              style={{
                display: 'block',
                width: '100%',
                textAlign: 'left',
                padding: '10px 16px',
                background: 'transparent',
                color: '#e0e0e0',
                border: 'none',
                borderBottom: '1px solid #0f3460',
                cursor: 'pointer',
              }}
            >
              <span
                style={{
                  display: '-webkit-box',
                  WebkitLineClamp: 2,
                  WebkitBoxOrient: 'vertical',
                  overflow: 'hidden',
                  fontSize: '13px',
                  overflowWrap: 'anywhere',
                }}
              >
                {q.content}
              </span>
              <time dateTime={q.timestamp} title={formatFullTimestamp(q.timestamp)} style={{ display: 'block', fontSize: '11px', color: '#a8a8c8', marginTop: '2px' }}>
                {formatTimestamp(q.timestamp)}
              </time>
            </button>
          </li>
        ))}
      </ol>
    </nav>
  );
}

