def edit(p, old, new):
    s=open(p).read(); assert old in s, (p, old); open(p,'w').write(s.replace(old,new))
edit('src/shared/types.ts', """  // App status
  GET_STATUS: 'app:status',""", """  // Clipboard (main-process Electron clipboard; navigator.clipboard is unreliable on file://)
  WRITE_CLIPBOARD: 'clipboard:write-text',

  // App status
  GET_STATUS: 'app:status',""")
edit('src/preload/preload.ts', """  GET_STATUS: 'app:status',
};""", """  WRITE_CLIPBOARD: 'clipboard:write-text',
  GET_STATUS: 'app:status',
};""")
edit('src/preload/preload.ts', """  conversation: {
    get: () => ipcRenderer.invoke(IPC_CHANNELS.GET_CONVERSATION),
  },""", """  conversation: {
    get: () => ipcRenderer.invoke(IPC_CHANNELS.GET_CONVERSATION),
  },
  clipboard: {
    writeText: (text: string) => ipcRenderer.invoke(IPC_CHANNELS.WRITE_CLIPBOARD, text),
  },""")
edit('src/renderer/types.d.ts', """        get: () => Promise<import('../shared/types').ConversationMessage[]>;
      };""", """        get: () => Promise<import('../shared/types').ConversationMessage[]>;
      };
      clipboard: {
        writeText: (text: string) => Promise<void>;
      };""")
edit('src/main/ipc-handlers.ts', "import { IpcMain } from 'electron';", "import { IpcMain, clipboard } from 'electron';")
edit('src/main/ipc-handlers.ts', """    return qaService.getConversation();
  });""", """    return qaService.getConversation();
  });

  // Clipboard
  ipcMain.handle(IPC_CHANNELS.WRITE_CLIPBOARD, async (_event, text: string) => {
    log.info('WRITE_CLIPBOARD', { length: typeof text === 'string' ? text.length : 0 });
    if (typeof text !== 'string') throw new Error('Clipboard text must be a string');
    clipboard.writeText(text);
  });""")
edit('src/renderer/components/QuestionPanel.tsx', "      await navigator.clipboard.writeText(text);", "      await window.knowledgeBase.clipboard.writeText(text);")
edit('scripts/smoke-conversation.js', "const { app, BrowserWindow, ipcMain } = require('electron');", "const { app, BrowserWindow, ipcMain, clipboard } = require('electron');")
edit('scripts/smoke-conversation.js', """  check('Copy succeeded (clipboard write)', copied);""", """  const firstAnswer = await wc.executeJavaScript(`document.querySelector('li[aria-label^="Assistant answered"] article > p').textContent`);
  check('Copy succeeded and clipboard holds the answer', copied && clipboard.readText() === firstAnswer);""")
edit('scripts/smoke-conversation.js', """  win.focus();
  // userGesture=true: navigator.clipboard requires a user activation, as a real click provides.
  await wc.executeJavaScript(`[...document.querySelectorAll('button')].find(b => b.textContent === 'Copy').click()`, true);""", """  await wc.executeJavaScript(`[...document.querySelectorAll('button')].find(b => b.textContent === 'Copy').click()`);""")
EOF
